select 
  from ai_publication
 where resource_type = #{resourceType} and resource_id = #{resourceId} and idempotency_key = #{key}

select coalesce(max(generation), 0) + 1
  from ai_publication
 where resource_type = #{resourceType} and resource_id = #{resourceId}

mapper.update:
update ai_publication
   set state = 'FAILED',
       error_code = 'PUBLICATION_TIMEOUT',
       error_message = '发布超时，请检查注册或运行时状态后重试',
       lease_owner = null,
       lease_until = null,
       updated_at = now()
 where id = #{id}
   and state = #{expectedState}
   and lease_owner = #{owner}
   and lease_until > now()
   and deadline_at < #{deadline}

update ai_outbox
   set status = 'DONE'
 where aggregate_type = #{aggregateType}
   and aggregate_id = #{aggregateId}
   and generation = #{generation}
   and event_type = #{eventType}

update ai_outbox
   set lease_until = now() + make_interval(secs => #{leaseSeconds})
 where id = #{id}
   and status = 'PENDING'
   and lease_owner = #{worker}
   and lease_until > now()

update ai_outbox
   set status = 'DONE', lease_owner = null, lease_until = null
 where id = #{id}
   and status = 'PENDING'
   and lease_owner = #{worker}
   and lease_until > now()
